[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CommerceForge Dev Docs</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0d1117;
      --bg-card: #161b22;
      --bg-card-hover: #1c2330;
      --border: #21262d;
      --border-light: #30363d;
      --text: #e6edf3;
      --text-muted: #8b949e;
      --text-dim: #6e7681;
      --accent: #00d4aa;
      --accent-dim: rgba(0, 212, 170, 0.12);
      --accent-blue: #475F91;
      --accent-blue-dim: rgba(71, 95, 145, 0.15);
      --green: #3fb950;
      --purple: #a371f7;
      --font: 'Inter', system-ui, -apple-system, sans-serif;
      --mono: 'JetBrains Mono', 'Fira Code', monospace;
    }

    html { scroll-behavior: smooth; }
    body { background: var(--bg); color: var(--text); font-family: var(--font); line-height: 1.6; font-size: 15px; min-height: 100vh; }
    a { color: inherit; text-decoration: none; }

    /* NAV */
    nav {
      position: sticky; top: 0; z-index: 100;
      background: rgba(13, 17, 23, 0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      padding: 0 24px;
    }
    .nav-inner {
      max-width: 1280px; margin: 0 auto;
      display: flex; align-items: center; height: 60px; gap: 8px;
    }
    .nav-logo { font-size: 16px; font-weight: 700; color: var(--text); letter-spacing: -0.3px; margin-right: 16px; display: flex; align-items: center; gap: 8px; }
    .nav-logo-icon { width: 26px; height: 26px; background: linear-gradient(135deg, var(--accent), var(--accent-blue)); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 13px; color: #fff; font-weight: 700; }
    .nav-links { display: flex; align-items: center; gap: 4px; flex: 1; }
    .nav-link { padding: 6px 12px; border-radius: 6px; font-size: 14px; font-weight: 500; color: var(--text-muted); transition: all .15s; }
    .nav-link:hover { color: var(--text); background: rgba(255,255,255,.05); }
    .nav-link.active { color: var(--text); }
    .nav-utils { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    .nav-search {
      display: flex; align-items: center; gap: 8px; padding: 6px 12px;
      background: var(--bg-card); border: 1px solid var(--border); border-radius: 8px;
      color: var(--text-muted); font-size: 13px; cursor: pointer; transition: all .15s;
    }
    .nav-search:hover { border-color: var(--border-light); color: var(--text); }
    .nav-btn { padding: 6px 14px; border-radius: 6px; font-size: 13px; font-weight: 500; border: 1px solid var(--border); color: var(--text-muted); background: transparent; cursor: pointer; transition: all .15s; font-family: var(--font); }
    .nav-btn:hover { border-color: var(--border-light); color: var(--text); background: rgba(255,255,255,.04); }
    .nav-toggle { display: none; }

    /* HERO */
    .hero { padding: 96px 24px 80px; text-align: center; position: relative; overflow: hidden; }
    .hero::before {
      content: '';
      position: absolute; inset: 0;
      background: radial-gradient(ellipse 80% 60% at 50% -10%, rgba(0,212,170,.08) 0%, transparent 70%),
                  radial-gradient(ellipse 60% 40% at 80% 80%, rgba(71,95,145,.06) 0%, transparent 60%);
      pointer-events: none;
    }
    .hero-badge { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: 20px; background: var(--accent-dim); border: 1px solid rgba(0,212,170,.25); color: var(--accent); font-size: 12px; font-weight: 500; margin-bottom: 24px; }
    .hero h1 { font-size: clamp(32px, 5vw, 52px); font-weight: 700; letter-spacing: -1px; line-height: 1.15; color: var(--text); max-width: 800px; margin: 0 auto 20px; }
    .hero h1 span { background: linear-gradient(135deg, var(--accent), #4dd8c0); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
    .hero-sub { font-size: 16px; color: var(--text-muted); max-width: 640px; margin: 0 auto 40px; line-height: 1.7; }
    .hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
    .btn-primary { display: inline-flex; align-items: center; gap: 8px; padding: 10px 20px; background: var(--accent); color: #0d1117; border-radius: 8px; font-weight: 600; font-size: 14px; transition: all .15s; }
    .btn-primary:hover { background: #00eabf; transform: translateY(-1px); }
    .btn-secondary { display: inline-flex; align-items: center; gap: 8px; padding: 10px 20px; background: transparent; color: var(--text); border: 1px solid var(--border-light); border-radius: 8px; font-weight: 500; font-size: 14px; transition: all .15s; }
    .btn-secondary:hover { border-color: var(--accent); color: var(--accent); transform: translateY(-1px); }

    /* SECTIONS */
    section { padding: 72px 24px; }
    .container { max-width: 1280px; margin: 0 auto; }
    .section-label { font-size: 12px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--accent); margin-bottom: 12px; }
    .section-title { font-size: clamp(22px, 3vw, 32px); font-weight: 700; letter-spacing: -0.5px; color: var(--text); margin-bottom: 12px; }
    .section-sub { font-size: 15px; color: var(--text-muted); max-width: 560px; line-height: 1.7; margin-bottom: 40px; }

    /* PRODUCT CARDS */
    .product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .product-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 14px; padding: 32px; transition: all .2s; position: relative; overflow: hidden;
    }
    .product-card::before {
      content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
      background: linear-gradient(90deg, transparent, var(--card-accent, var(--accent)), transparent);
      opacity: 0; transition: opacity .2s;
    }
    .product-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); transform: translateY(-2px); }
    .product-card:hover::before { opacity: 1; }
    .card-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 20px; margin-bottom: 20px; }
    .card-icon-green { background: rgba(63,185,80,.12); color: var(--green); }
    .card-icon-blue { background: rgba(71,95,145,.15); color: #7aa2d4; }
    .card-icon-purple { background: rgba(163,113,247,.12); color: var(--purple); }
    .product-card h3 { font-size: 18px; font-weight: 600; color: var(--text); margin-bottom: 10px; }
    .product-card p { font-size: 14px; color: var(--text-muted); line-height: 1.65; margin-bottom: 24px; }
    .card-link { display: inline-flex; align-items: center; gap: 6px; color: var(--accent); font-size: 13px; font-weight: 600; transition: gap .15s; }
    .card-link:hover { gap: 10px; }
    .product-card:nth-child(1) { --card-accent: var(--green); }
    .product-card:nth-child(2) { --card-accent: #7aa2d4; }
    .product-card:nth-child(3) { --card-accent: var(--purple); }

    /* CLI SECTION */
    .cli-section { background: var(--bg-card); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
    .cli-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: start; }
    .accordion { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
    .accordion-item { border-bottom: 1px solid var(--border); }
    .accordion-item:last-child { border-bottom: none; }
    .accordion-trigger {
      width: 100%; display: flex; align-items: center; justify-content: space-between;
      padding: 16px 20px; background: none; border: none; color: var(--text);
      font-size: 14px; font-weight: 600; cursor: pointer; font-family: var(--font); transition: background .15s; text-align: left;
    }
    .accordion-trigger:hover { background: rgba(255,255,255,.03); }
    .accordion-trigger.open { color: var(--accent); }
    .accordion-chevron { font-size: 16px; color: var(--text-dim); transition: transform .2s; flex-shrink: 0; }
    .accordion-trigger.open .accordion-chevron { transform: rotate(180deg); color: var(--accent); }
    .accordion-content { max-height: 0; overflow: hidden; transition: max-height .3s ease; }
    .accordion-content.open { max-height: 400px; }
    .accordion-body { padding: 0 20px 20px; }
    .step-list { list-style: none; margin-bottom: 16px; }
    .step-list li { display: flex; gap: 12px; align-items: flex-start; padding: 6px 0; font-size: 13px; color: var(--text-muted); }
    .step-num { width: 20px; height: 20px; border-radius: 50%; background: var(--accent-dim); border: 1px solid rgba(0,212,170,.25); color: var(--accent); font-size: 11px; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 1px; }
    .code-block { background: #010409; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
    .code-tabs { display: flex; border-bottom: 1px solid var(--border); background: rgba(255,255,255,.02); }
    .code-tab { padding: 8px 16px; font-size: 12px; font-weight: 500; color: var(--text-dim); cursor: pointer; border-bottom: 2px solid transparent; transition: all .15s; font-family: var(--font); background: none; border-top: none; border-left: none; border-right: none; }
    .code-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
    .code-tab:hover:not(.active) { color: var(--text-muted); }
    .code-content { display: none; padding: 14px 16px; font-family: var(--mono); font-size: 13px; line-height: 1.6; }
    .code-content.active { display: block; }
    .code-comment { color: #6e7681; }
    .code-cmd { color: var(--accent); }
    .code-str { color: #a5d6ff; }
    .code-flag { color: var(--purple); }
    .init-cmd { display: flex; align-items: center; gap: 10px; padding: 12px 16px; background: rgba(0,212,170,.04); border: 1px solid rgba(0,212,170,.15); border-radius: 8px; font-family: var(--mono); font-size: 13px; color: var(--text-muted); margin-top: 12px; }
    .init-cmd span { color: var(--accent); }
    .copy-btn { margin-left: auto; padding: 2px 8px; border-radius: 4px; background: rgba(255,255,255,.06); border: none; color: var(--text-dim); cursor: pointer; font-size: 11px; font-family: var(--font); transition: all .15s; }
    .copy-btn:hover { background: rgba(255,255,255,.1); color: var(--text); }

    /* LAUNCH CTA */
    .launch-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
    .launch-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 14px; padding: 32px; display: flex; flex-direction: column; gap: 16px; transition: all .2s;
    }
    .launch-card:hover { border-color: var(--border-light); transform: translateY(-2px); }
    .launch-card h3 { font-size: 17px; font-weight: 600; color: var(--text); }
    .launch-card p { font-size: 14px; color: var(--text-muted); line-height: 1.65; flex: 1; }
    .btn-outline { display: inline-flex; align-items: center; gap: 6px; padding: 9px 18px; border: 1px solid var(--accent); color: var(--accent); border-radius: 8px; font-size: 13px; font-weight: 600; transition: all .15s; width: fit-content; }
    .btn-outline:hover { background: var(--accent-dim); }

    /* COMMUNITY */
    .community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
    .community-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 12px; padding: 24px; transition: all .2s; display: flex; flex-direction: column; gap: 12px;
    }
    .community-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); transform: translateY(-2px); }
    .community-icon { font-size: 22px; color: var(--accent-blue); }
    .community-card h4 { font-size: 14px; font-weight: 600; color: var(--text); }
    .community-card p { font-size: 13px; color: var(--text-muted); line-height: 1.6; flex: 1; }
    .community-link { display: inline-flex; align-items: center; gap: 4px; color: var(--accent); font-size: 12px; font-weight: 600; transition: gap .15s; }
    .community-link:hover { gap: 8px; }

    /* FOOTER */
    footer { background: var(--bg-card); border-top: 1px solid var(--border); padding: 56px 24px 32px; }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-top { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 40px; }
    .footer-brand { display: flex; flex-direction: column; gap: 12px; }
    .footer-logo { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 15px; }
    .footer-logo-icon { width: 24px; height: 24px; background: linear-gradient(135deg, var(--accent), var(--accent-blue)); border-radius: 5px; display: flex; align-items: center; justify-content: center; font-size: 11px; color: #fff; font-weight: 700; }
    .footer-tagline { font-size: 13px; color: var(--text-dim); line-height: 1.6; max-width: 200px; }
    .footer-col h5 { font-size: 12px; font-weight: 600; letter-spacing: .8px; text-transform: uppercase; color: var(--text-dim); margin-bottom: 14px; }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
    .footer-col li a { font-size: 13px; color: var(--text-muted); transition: color .15s; }
    .footer-col li a:hover { color: var(--text); }
    .footer-bottom { border-top: 1px solid var(--border); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; }
    .footer-copy { font-size: 12px; color: var(--text-dim); }

    /* DIVIDER */
    .section-divider { border: none; border-top: 1px solid var(--border); }

    /* RESPONSIVE */
    @media (max-width: 1024px) {
      .product-grid { grid-template-columns: repeat(2, 1fr); }
      .cli-layout { grid-template-columns: 1fr; gap: 40px; }
      .footer-top { grid-template-columns: 1fr 1fr; }
      .community-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 768px) {
      .product-grid { grid-template-columns: 1fr; }
      .launch-grid { grid-template-columns: 1fr; }
      .community-grid { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr; gap: 32px; }
      .nav-links { display: none; }
      .nav-toggle { display: flex; align-items: center; gap: 4px; padding: 6px 10px; background: none; border: 1px solid var(--border); border-radius: 6px; color: var(--text-muted); cursor: pointer; font-size: 13px; font-family: var(--font); }
      .hero-ctas { flex-direction: column; align-items: center; }
    }
  </style>
</head>
