<!-- CLI SETUP -->
<section class="cli-section">
  <div class="container">
    <div class="cli-layout">
      <div>
        <div class="section-label">CLI 3.0</div>
        <h2 class="section-title">Accelerate development with CommerceForge CLI 3.0</h2>
        <p class="section-sub">Initialize new apps, themes, and headless storefronts in an instant. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>

        <div class="accordion" id="cli-accordion">
          <!-- Apps -->
          <div class="accordion-item">
            <button class="accordion-trigger open" onclick="toggleAccordion(this, 'acc-apps')" aria-expanded="true">
              <span><i class="ri-apps-2-line" style="margin-right:8px;color:var(--green);"></i>Apps</span>
              <i class="ri-arrow-down-s-line accordion-chevron"></i>
            </button>
            <div class="accordion-content open" id="acc-apps">
              <div class="accordion-body">
                <ul class="step-list">
                  <li><span class="step-num">1</span>Install CommerceForge CLI globally.</li>
                  <li><span class="step-num">2</span>Navigate to the directory where you want to create your app.</li>
                  <li><span class="step-num">3</span>Run the command below to create a new app — added as a new subdirectory.</li>
                </ul>
                <div class="code-block">
                  <div class="code-tabs">
                    <button class="code-tab active" onclick="switchTab(this, 'apps-npm')">npm</button>
