                  </div>
                  <div class="code-content active" id="apps-npm"><span class="code-comment"># Install CLI globally</span>
<span class="code-cmd">npm</span> i <span class="code-flag">-g</span> <span class="code-str">@commerceforge/cli@latest</span></div>
                  <div class="code-content" id="apps-yarn"><span class="code-comment"># Install CLI globally</span>
<span class="code-cmd">yarn</span> global add <span class="code-str">@commerceforge/cli@latest</span></div>
                  <div class="code-content" id="apps-pnpm"><span class="code-comment"># Install CLI globally</span>
<span class="code-cmd">pnpm</span> add <span class="code-flag">-g</span> <span class="code-str">@commerceforge/cli@latest</span></div>
                </div>
                <div class="init-cmd"><i class="ri-terminal-line" style="color:var(--accent);"></i> <span>commerceforge app init</span> <button class="copy-btn" onclick="copyCmd('commerceforge app init', this)">copy</button></div>
              </div>
            </div>
          </div>
          <!-- Themes -->
          <div class="accordion-item">
            <button class="accordion-trigger" onclick="toggleAccordion(this, 'acc-themes')" aria-expanded="false">
