<script>
  function toggleAccordion(trigger, contentId) {
    const allTriggers = document.querySelectorAll('.accordion-trigger');
    const allContents = document.querySelectorAll('.accordion-content');

    allTriggers.forEach(t => { if (t !== trigger) { t.classList.remove('open'); t.setAttribute('aria-expanded','false'); } });
    allContents.forEach(c => { if (c.id !== contentId) c.classList.remove('open'); });

    const content = document.getElementById(contentId);
    const isOpen = content.classList.contains('open');
    if (isOpen) {
      content.classList.remove('open');
      trigger.classList.remove('open');
      trigger.setAttribute('aria-expanded','false');
    } else {
      content.classList.add('open');
      trigger.classList.add('open');
      trigger.setAttribute('aria-expanded','true');
    }
  }

  function switchTab(tab, contentId) {
    const block = tab.closest('.code-block');
    block.querySelectorAll('.code-tab').forEach(t => t.classList.remove('active'));
    block.querySelectorAll('.code-content').forEach(c => c.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById(contentId).classList.add('active');
  }

  function copyCmd(text, btn) {
    navigator.clipboard.writeText(text).then(() => {
      btn.textContent = 'copied!';
      setTimeout(() => btn.textContent = 'copy', 1500);
    });
  }
</script>
